SELECT DISTINCT V2.SEQPRODUTO, PX.DESCCOMPLETA, YF.SEQCATEGORIA, YF.CATEGORIA FROM MLFV_BASENFE V1 JOIN MFLV_BASEDFITEM V2 ON V2.NROEMPRESA = V1.NROEMPRESA AND V2.SEQNF = V1.SEQNF AND V2.TIPNOTAFISCAL = V1.TIPNOTAFISCAL AND V2.SERIEDF = V1.SERIENF AND V2.NUMERODF = V1.NUMERONF AND V2.SEQPESSOA = V1.SEQPESSOA INNER JOIN MAP_PRODUTO PX ON PX.SEQPRODUTO = V2.SEQPRODUTO LEFT JOIN MAP_FAMFORNEC FPX ON FPX.SEQFAMILIA = PX.SEQFAMILIA AND FPX.PRINCIPAL = 'S' LEFT JOIN MAP_FAMDIVCATEG XF ON XF.SEQFAMILIA = PX.SEQFAMILIA AND XF.NRODIVISAO = 1 LEFT JOIN MAP_CATEGORIA YF ON XF.SEQCATEGORIA = YF.SEQCATEGORIA AND YF.NIVELHIERARQUIA = 1 WHERE V1.TIPNOTAFISCAL = 'S' AND V1.CODGERALOPER = 800 AND NVL(V1.STATUSNF, 'A') != 'C' AND V1.DTAEMISSAO >= TO_DATE('01/05/2026', 'DD/MM/YYYY') AND V1.DTAEMISSAO < TO_DATE('02/05/2026', 'DD/MM/YYYY') + 1 AND FPX.SEQFORNECEDOR = 16491
